mapper.select:
select d.id, d.name, d.category_id, d.price, d.image, d.description, d.status, IFNULL(d.update_time, NOW()) as updateTime, c.name as categoryName from dish d left join category c on d.category_id=c.id
and d.name like concat('%', #{dishPageQueryDTO.name}, '%')
and d.category_id = #{dishPageQueryDTO.categoryId}
and d.status = #{dishPageQueryDTO.status}
order by d.create_time desc

select * from dish


        and name like concat('%', #{name}, '%')


        and category_id = #{categoryId}


        and status = #{status}


order by create_time desc

select count(id) from dish


        and status = #{status}


        and category_id = #{categoryId}
